use vstd::prelude::*;

verus! {

/// Possible data-type representations.
pub enum DataType {
    ScalarInt,
    ScalarFloat,
    ScalarComplex,
    ScalarBool,
    ScalarString,
    ArrayType,
    CompositeType,
    UnknownType,
}

/// Spec-level predicate characterizing exactly the scalar variants.
pub open spec fn is_scalar_type(rep: DataType) -> bool {
    rep == DataType::ScalarInt
    || rep == DataType::ScalarFloat
    || rep == DataType::ScalarComplex
    || rep == DataType::ScalarBool
    || rep == DataType::ScalarString
}

/// Returns `true` iff `rep` denotes one of the scalar types.
pub fn issctype(rep: DataType) -> (result: bool)
    ensures
        result <==> is_scalar_type(rep),
        // Optional strengthening: spelling out the full iff over all variants
        result == (
            rep == DataType::ScalarInt
            || rep == DataType::ScalarFloat
            || rep == DataType::ScalarComplex
            || rep == DataType::ScalarBool
            || rep == DataType::ScalarString
        ),
{
    match rep {
        DataType::ScalarInt
        | DataType::ScalarFloat
        | DataType::ScalarComplex
        | DataType::ScalarBool
        | DataType::ScalarString => true,

        DataType::ArrayType
        | DataType::CompositeType
        | DataType::UnknownType => false,
    }
}

} // verus!

